<?php require '../config/config.php';login();$q=trim($_GET['q']??'');$rows=[];if($q){$s=$pdo->prepare("SELECT b.code,b.title,b.author,COUNT(c.id) total,SUM(c.status='tersedia') available FROM books b LEFT JOIN copies c ON c.book_id=b.id WHERE b.title LIKE ? OR b.code LIKE ? OR b.author LIKE ? GROUP BY b.id");$x="%$q%";$s->execute([$x,$x,$x]);$rows=$s->fetchAll();}?><!doctype html><link rel=stylesheet href=style.css><div class=layout><?php include 'nav.php'?><main class=main><h1>🔎 Search Buku</h1><form class=search><input name=q value="<?=e($q)?>" placeholder="Judul/kode/penulis"><button>Cari</button></form><br><table class=table><tr><th>Kode</th><th>Judul</th><th>Penulis</th><th>Ketersediaan</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><?=($r['available']??0)>0?'🟢 '.$r['available'].' tersedia':'🔴 Tidak tersedia'?></td></tr><?php endforeach?></table></main></div>
